'use strict';
const plural=(n,word)=>`${n} ${word}${n===1?'':'s'}`;
const $=id=>document.getElementById(id),t=OrionI18n.t;
let variant=OrionProgress.variant('solutions'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,water=1,total=2,dissolved=0,observed=false,sawResidue=false,solved=false,hintDepth=0,state='ready',saveFailed=false;
function initial(v=variant,s=stage){const w=1+v%3;return s===0?[1,2+v]:s===1?[w,1]:[w,2*w+2+v%2];}
function equilibrium(w,n){return Math.min(n,2*w);}
function resetTrial(){[water,total]=initial();dissolved=0;observed=false;sawResidue=false;solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('solutions')){variant=v;stage=0;resetTrial();}
function addWater(){if(solved||stage===1||water>=6||stage===2&&!sawResidue)return;water++;observed=false;state='changed';render();}
function addCrystal(){if(solved||stage!==1||total>=16)return;total++;observed=false;state='changed';render();}
function check(){if(solved)return;dissolved=equilibrium(water,total);observed=true;const residue=total-dissolved;if(stage===2&&residue>0)sawResidue=true;
solved=stage===0?total<2*water:stage===1?residue>0:sawResidue&&residue===0;
state=solved?'success':residue>0?'residue':total===2*water?'full':'spare';
if(solved&&stage===2)saveFailed=!OrionProgress.earn('clarity');render();if(solved&&stage<2)$('next').focus();}
function hints(){return [t('The crystals do not vanish. Look for tiny dissolved dots and solid chunks. Try a change, then observe again.','晶體不是消失了。看看已溶解的小點和固體晶塊。改變條件，再觀察。'),t('In this imaginary model, each cup holds up to 2 dissolved units. Stirring helps them dissolve faster; it does not increase that limit.','在這個虛構模型中，每杯水最多溶解 2 份。攪拌可加快溶解，但不提高上限。'),stage===0?t(`Use at least ${Math.floor(total/2)+1} cups, so all ${total} units dissolve with room for more.`,`用至少 ${Math.floor(total/2)+1} 杯水，讓 ${total} 份全部溶解，還有餘力。`):stage===1?t(`With ${water} cups, add more than ${2*water} crystal units, then stir & wait.`,`有 ${water} 杯水，加入超過 ${2*water} 份晶體，再攪拌並等待。`):!sawResidue?t('First stir & wait to observe solid left. Then you can add water.','先攪拌並等待，觀察剩餘固體，之後就可以加水。'):t(`Reach at least ${Math.ceil(total/2)} cups, then stir & wait again.`,`加到至少 ${Math.ceil(total/2)} 杯水，再攪拌並等待。`)];}
function draw(){const top=165-water*18,remaining=total-dissolved;let dots='',chunks='';for(let i=0;i<dissolved;i++)dots+=`<circle cx="${112+(i%4)*43}" cy="${top+15+Math.floor(i/4)*20}" r="5" fill="#e3bdff"/>`;for(let i=0;i<remaining;i++)chunks+=`<path d="M${100+i*11} 177 l5 -11 5 11 -5 5Z" fill="#b688e0" stroke="#ecdbff"/>`;
$('diagram').innerHTML=`<svg viewBox="0 0 380 210" aria-hidden="true"><defs><clipPath id="bowlClip"><path d="M65 30H315L290 190H90Z"/></clipPath><linearGradient id="aqua" x2="0" y2="1"><stop stop-color="#469bad" stop-opacity=".8"/><stop offset="1" stop-color="#1c6476"/></linearGradient></defs><path d="M65 30H315L290 190H90Z" fill="#153b48" stroke="#b6d8d5" stroke-width="3"/><g clip-path="url(#bowlClip)"><rect x="66" y="${top}" width="250" height="180" fill="url(#aqua)"/><path d="M70 ${top}Q130 ${top-5}190 ${top}T310 ${top}" stroke="#89e5e8" fill="none"/>${dots}${chunks}</g><path d="M58 28H322" stroke="#d6e5df" stroke-width="5" stroke-linecap="round"/></svg>`;
$('diagram').setAttribute('aria-label',t(`Bowl: ${plural(water,"cup")} of water, ${plural(dissolved,"dissolved unit")}, ${plural(remaining,"solid unit")} left.`,`碗裡有 ${water} 杯水、${dissolved} 份已溶解、${remaining} 份固體剩餘。`));}
function render(){const complete=solved&&stage===2,progress=stage+Number(solved),residue=total-dissolved;window.OrionDiscovery?.update(complete);document.title=t('The Crystal Spring · Orion','晶泉的秘密 · Orion');$('stageTitle').textContent=t(`Bowl ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 碗 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Spring seals · ${progress} / 3`,`晶泉封印 · ${progress} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);draw();
$('amount').textContent=t(`${plural(water,"cup")} of water · ${plural(total,"crystal unit")} added`,`${water} 杯水 · 已加入 ${total} 份晶體`);$('water').disabled=solved||stage===1||water===6||stage===2&&!sawResidue;$('crystal').disabled=solved||stage!==1||total===16;
$('controlNote').textContent=stage===1?t('Water is fixed for this test. Add crystals, then observe.','這次水量固定。加晶體，再觀察。'):stage===2&&!sawResidue?t('First observe this sample. The water jug unlocks after you see solid left.','先觀察這份樣本。看見剩餘固體後，就能使用水壺。'):t('Crystal amount is fixed. Add water to change this sample.','晶體份數固定。加水來改變這份樣本。');
$('goal').textContent=[t('Seal 1: dissolve all the crystals AND leave room for more. Add water and observe.','封印 1：讓晶體全部溶解，而且仍有餘力溶解更多。加水並觀察。'),t('Seal 2: find the limit! Add enough crystals that some solid stays after stirring and waiting.','封印 2：找出上限！加晶體，直到攪拌並等待後仍有固體剩餘。'),t('Seal 3: first observe solid left, then add water until it can all dissolve.','封印 3：先觀察剩餘固體，再加水，直到全部可以溶解。')][stage];
$('reading').textContent=t(`Dissolved: ${dissolved} · Solid left: ${residue}`,`已溶解：${dissolved} · 剩餘固體：${residue}`)+(observed?'':t(' · Ready to observe',' · 準備觀察'));
$('evidence').textContent=stage===2&&sawResidue?t('✓ You observed solid left before adding water.','✓ 你已在加水前觀察到剩餘固體。'):'';
const messages={ready:t('The bowl is ready. Press Stir & wait to observe what can dissolve.','樣本準備好了。按「攪拌並等待」，觀察能溶解多少。'),changed:t('Sample changed. Stir & wait again to see the new result.','樣本改變了。再次攪拌並等待，看看新結果。'),residue:t('Some solid remains. The water has reached its dissolving limit. Try adding water.','還有固體剩餘。水已達到溶解上限，試試加水。'),full:t('All dissolved, but the water is exactly full: saturated. It has no room for more yet.','全部溶解，但剛好達到上限：飽和了，暫時沒有餘力。'),spare:t('All dissolved and there is still room: unsaturated. Keep exploring the goal.','全部溶解，而且仍有餘力：未飽和。繼續探索目標。'),success:stage===0?t('All dissolved, with room for more! This solution is unsaturated.','全部溶解，仍有餘力！這是未飽和溶液。'):stage===1?t('Solid remains after waiting. The solution has reached its limit: saturated.','等待後仍有固體剩餘。溶液已達上限：飽和了。'):t('More water let the remaining crystals dissolve. All units are still in the bowl!','更多水讓剩餘晶體溶解了。所有份數仍在碗裡！')};$('feedback').textContent=messages[state];
$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('clarity')?t('Clarity Sigil saved in your collection.','澄明符印已存入收藏。'):'';}
$('water').onclick=addWater;$('crystal').onclick=addCrystal;$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('check').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('solutions',variant);observedVariant=OrionProgress.variant('solutions');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('clarity');render();};
function syncProgress(){const v=OrionProgress.variant('solutions'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('clarity')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
